<span class="card-countries"><?php $countries=$item['countries'] ?? []; foreach (array_slice($countries,0,2) as $country): ?><span class="card-destination"><?php if ($country['flag']): ?><img class="country-flag" src="<?= e((base_url() . ($country['flag']))) ?>" alt="ธง<?= e($country['name']) ?>" title="<?= e($country['name']) ?>" width="24" height="18" loading="lazy"><?php else: ?><span aria-hidden="true"><i class="material-icons" aria-hidden="true">location_on</i></span><?php endif ?><span><?= e($country['name']) ?></span></span><?php endforeach ?><?php if (count($countries)>2): ?><span class="country-overflow" title="<?= e(implode(', ',array_column(array_slice($countries,2),'name'))) ?>">+ อีก <?= count($countries)-2 ?> ประเทศ</span><?php endif ?><?php if (!$countries): ?><span class="card-destination"><i class="material-icons" aria-hidden="true">location_on</i> <?= e($item['destination']) ?></span><?php endif ?></span>
